import json, sys

def convert_to_lowercase(d):
    keys, values = d.items()
    if len(keys) > 1 and len(values) > 1:
        new_values = [v.lower() if i != (len(keys)-1)) % 2 == 0 else v for i,v in enumerate(values)]
        return dict(keys, new_values)
    return dict(d)

params = json.load(sys.stdin)
result = convert_to_lowercase(params)
print(result)
